['id'])) ?>" target="_blank" rel="noopener"><i class="bi bi-eye mr-2" aria-hidden="true"></i>Preview</a><a class="dropdown-item" href="<?= esc(base_url('admin/doctor-documents/download/' . (int) $row['id'])) ?>"><i class="bi bi-download mr-2" aria-hidden="true"></i>Download</a><?php if (function_exists('can') ? can('doctor_document.edit') : true): ?><button type="button" class="dropdown-item" onclick="editDoctorDocumentForm(<?= (int) $row['id'] ?>)"><i class="bi bi-pencil-square mr-2" aria-hidden="true"></i>Edit details</button><button type="button" class="dropdown-item" onclick="editDoctorDocumentForm(<?= (int) $row['id'] ?>, true)"><i class="bi bi-arrow-repeat mr-2" aria-hidden="true"></i>Replace file</button><?php endif; ?><?php if (function_exists('can') ? can('doctor_document.delete') : true): ?><div class="dropdown-divider"></div><form method="post" action="<?= esc(base_url('admin/doctor-documents/delete/' . (int) $row['id'])) ?>" class="doctor-document-delete-form"><?= csrf_field() ?><button type="submit" class="dropdown-item text-danger js-doctor-document-delete"><i class="bi bi-trash mr-2" aria-hidden="true"></i>Delete document</button></form><?php endif; ?></div></div></td></tr>
        <?php endforeach; else: ?><tr><td colspan="5"><div class="doctor-document-empty-state"><span class="doctor-document-empty-icon"><i class="bi bi-file-earmark-x" aria-hidden="true"></i></span><h3>No documents found</h3><p><?= !empty($filters['search']) || ($filters['status'] ?? '') !== '' ? 'Try clearing or changing your filters.' : 'Upload a doctor document to start building the register.' ?></p><?php if (!empty($filters['search']) || ($filters['status'] ?? '') !== ''): ?><a class="btn btn-sm btn-outline-secondary" href="<?= esc(current_url()) ?>">Clear filters</a><?php endif; ?></div></td></tr><?php endif; ?>
